-- INVIHUB PREMIUM V1 | mira reforcada | missoes | 14 rotas oficiais.
-- Menu preto, branco e cinza; script compactado em LZW + Base64.
-- Clone local: NAO aparece para os demais jogadores; interacoes dependem do servidor.
local payload = ""
local function unpackPayload(s)
    local alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map={}
    for i=1,#alphabet do map[string.byte(alphabet,i)]=i-1 end
    local chunks={}
    for i=1,#s,4 do
        local a,b,c,d=string.byte(s,i,i+3)
        local n=map[a]*262144+map[b]*4096+(map[c] or 0)*64+(map[d] or 0)
        local b1=math.floor(n/65536)%256
        local b2=math.floor(n/256)%256
        local b3=n%256
        if c==61 then chunks[#chunks+1]=string.char(b1)
        elseif d==61 then chunks[#chunks+1]=string.char(b1,b2)
        else chunks[#chunks+1]=string.char(b1,b2,b3) end
    end
    local packed=table.concat(chunks)
    local dict={}
    for i=0,255 do dict[i]=string.char(i) end
    local first=string.byte(packed,1)*256+string.byte(packed,2)
    local previous=dict[first]
    if not previous then error("Invihub: cabeçalho de dados inválido") end
    local output={previous}
    local nextCode=256
    for i=3,#packed,2 do
        local h,l=string.byte(packed,i,i+1)
        local code=h*256+l
        local entry=dict[code]
        if entry==nil then
            if code~=nextCode then error("Invihub: dados compactados inválidos") end
            entry=previous..string.sub(previous,1,1)
        end
        output[#output+1]=entry
        if nextCode<65536 then
            dict[nextCode]=previous..string.sub(entry,1,1)
            nextCode=nextCode+1
        end
        previous=entry
    end
    return table.concat(output)
end
local source=unpackPayload(payload)
local fn,err=loadstring(source)
if not fn then error("Invihub: falha ao interpretar Lua: "..tostring(err)) end
return fn()
